1	package com.example.starter.runway;
2	
3	import com.example.starter.runway.dto.*;
4	import jakarta.validation.Valid;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.web.bind.annotation.*;
7	
8	import java.util.List;
9	
10	/**
11	 * 跑道临时关闭巡检与开放决策 API。
12	 */
13	@RestController
14	@RequestMapping("/api")
15	public class RunwayController {
16	
17	    private final RunwayService service;
18	
19	    public RunwayController(RunwayService service) {
20	        this.service = service;
21	    }
22	
23	    /**
24	     * 接报：触发临时关闭并同步发布关闭通告；requestId 幂等。
25	     */
26	    @PostMapping("/runway-events/reports")
27	    @ResponseStatus(HttpStatus.CREATED)
28	    public ReportResponse report(@Valid @RequestBody ReportRequest request) {
29	        return service.report(request);
30	    }
31	
32	    /**
33	     * 巡检开始：15分钟迟延判定、低能见度双人校验；归档后仅登记迟到记录。
34	     */
35	    @PostMapping("/runway-events/{eventId}/inspections")
36	    @ResponseStatus(HttpStatus.CREATED)
37	    public InspectionResponse startInspection(@PathVariable long eventId,
38	                                              @Valid @RequestBody InspectionRequest request) {
39	        return service.startInspection(eventId, request);
40	    }
41	
42	    /**
43	     * 巡检评估：记录摩擦系数与评估类型；requestId 幂等。
44	     */
45	    @PostMapping("/runway-events/{eventId}/assessments")
46	    @ResponseStatus(HttpStatus.CREATED)
47	    public AssessmentResponse assess(@PathVariable long eventId,
48	                                     @Valid @RequestBody AssessmentRequest request) {
49	        return service.assess(eventId, request);
50	    }
51	
52	    /**
53	     * 恢复开放：与航行通告发布同一事务完成；requestId 幂等。
54	     */
55	    @PostMapping("/runway-events/{eventId}/reopen")
56	    public ReopenResponse reopen(@PathVariable long eventId,
57	                                 @Valid @RequestBody ReopenRequest request) {
58	        return service.reopen(eventId, request);
59	    }
60	
61	    /**
62	     * 归档：终态；重复归档返回幂等成功。
63	     */
64	    @PostMapping("/runway-events/{eventId}/archive")
65	    public ArchiveResponse archive(@PathVariable long eventId) {
66	        return service.archive(eventId);
67	    }
68	
69	    /**
70	     * 事件详情与状态时间线（可复算）。
71	     */
72	    @GetMapping("/runway-events/{eventId}")
73	    public EventDetailResponse detail(@PathVariable long eventId) {
74	        return service.getDetail(eventId);
75	    }
76	
77	    /**
78	     * 摩擦系数轨迹（可复算）。
79	     */
80	    @GetMapping("/runway-events/{eventId}/friction-trajectory")
81	    public List<FrictionPoint> frictionTrajectory(@PathVariable long eventId) {
82	        return service.getFrictionTrajectory(eventId);
83	    }
84	
85	    /**
86	     * 通告记录（可复算）。
87	     */
88	    @GetMapping("/runway-events/{eventId}/notams")
89	    public List<NotamView> notams(@PathVariable long eventId) {
90	        return service.getNotams(eventId);
91	    }
92	
93	    /**
94	     * 上报气象读数（合成数据）。
